tasks.tests:
var b = $('button');
assert(b, 'Нет тега <button>');
equal(style(b, 'background-color'), 'rgb(37, 99, 235)', 'Фон (bg-blue-600)');
equal(style(b, 'color'), 'rgb(255, 255, 255)', 'Цвет текста (text-white)');
equal(style(b, 'padding-left'), '16px', 'Боковые отступы (px-4)');
equal(style(b, 'padding-top'), '8px', 'Вертикальные отступы (py-2)');
equal(style(b, 'border-top-left-radius'), '8px', 'Скругление (rounded-lg)');

var h = $('header');
assert(h, 'Нет тега <header>');
equal(style(h, 'display'), 'flex', 'display (flex)');
equal(style(h, 'justify-content'), 'space-between', 'justify-between');
equal(style(h, 'align-items'), 'center', 'items-center');
equal(style(h, 'padding-top'), '16px', 'Отступы (p-4)');
equal($$('header span').length, 2, 'Количество элементов внутри');

var d = $('div');
assert(d, 'Нет тега <div>');
equal(style(d, 'max-width'), '384px', 'Ограничение ширины (max-w-sm)');
equal(style(d, 'margin-left'), style(d, 'margin-right'), 'mx-auto: отступы слева и справа равны');
equal(style(d, 'padding-top'), '24px', 'Отступы (p-6)');
equal(style(d, 'border-top-left-radius'), '12px', 'Скругление (rounded-xl)');
var h = $('div h2');
assert(h, 'Внутри div нужен <h2>');
equal(style(h, 'font-size'), '20px', 'Размер заголовка (text-xl)');
equal(style(h, 'font-weight'), '700', 'Жирность (font-bold)');

var g = $('div');
assert(g, 'Нет внешнего <div>');
equal(style(g, 'display'), 'grid', 'display (grid)');
assert(style(g, 'gap').indexOf('16px') === 0, 'gap-4 должен дать 16px, а сейчас: ' + style(g, 'gap'));
var cards = $$('div > div');
equal(cards.length, 3, 'Карточек внутри');
equal(style(cards[0], 'padding-top'), '16px', 'Отступ карточки (p-4)');

var s = $('section');
assert(s, 'Нет тега <section>');
equal(style(s, 'display'), 'grid', 'display (класс grid)');
equal(style(s, 'gap'), '16px', 'Расстояние между ячейками (gap-4)');
var cols = style(s, 'grid-template-columns').split(' ').filter(function(x){ return x; });
equal(cols.length, 3, 'Количество колонок (grid-cols-3)');
var cards = $$('section > div');
equal(cards.length, 3, 'Количество карточек');
cards.forEach(function(c, i){
  equal(style(c, 'background-color'), 'rgb(255, 255, 255)', 'Фон карточки ' + (i + 1) + ' (bg-white)');
  equal(style(c, 'padding-top'), '16px', 'Отступ карточки ' + (i + 1) + ' (p-4)');
  equal(style(c, 'border-top-left-radius'), '8px', 'Скругление карточки ' + (i + 1) + ' (rounded-lg)');
});

var b = $('button');
assert(b, 'Нет тега <button>');
equal(style(b, 'background-color'), 'rgb(37, 99, 235)', 'Фон (bg-blue-600)');
equal(style(b, 'color'), 'rgb(255, 255, 255)', 'Цвет текста (text-white)');
equal(style(b, 'padding-left'), '16px', 'Отступ по горизонтали (px-4)');
equal(style(b, 'padding-top'), '8px', 'Отступ по вертикали (py-2)');
equal(style(b, 'border-top-left-radius'), '8px', 'Скругление (rounded-lg)');
var cls = b.className;
assert(cls.indexOf('hover:bg-blue-700') !== -1, 'Нет класса hover:bg-blue-700');
assert(cls.indexOf('focus-visible:ring-2') !== -1, 'Нет класса focus-visible:ring-2');
assert(cls.indexOf('disabled:opacity-50') !== -1, 'Нет класса disabled:opacity-50');

var a = $('article');
assert(a, 'Нет тега <article>');
equal(style(a, 'display'), 'flex', 'display (класс flex)');
equal(style(a, 'flex-direction'), 'column', 'Направление (flex-col)');
equal(style(a, 'justify-content'), 'space-between', 'Распределение (justify-between)');
equal(style(a, 'height'), '192px', 'Высота (h-48)');
equal(style(a, 'background-color'), 'rgb(255, 255, 255)', 'Фон (bg-white)');
equal(style(a, 'padding-top'), '16px', 'Отступ (p-4)');
equal(style(a, 'border-top-left-radius'), '12px', 'Скругление (rounded-xl)');
assert($('article h3'), 'Заголовок должен остаться внутри');
assert($('article button'), 'Кнопка должна остаться внутри');

var s = $('section');
assert(s, 'Нет тега <section>');
equal(style(s, 'display'), 'grid', 'Секция должна быть сеткой (grid)');
equal(style(s, 'gap'), '16px', 'Расстояние между карточками (gap-4)');
assert(s.className.indexOf('md:grid-cols-2') !== -1, 'Нет класса md:grid-cols-2');
var cards = $$('section > article');
equal(cards.length, 2, 'Карточек должно быть две');
cards.forEach(function(c, i){
  var n = i + 1;
  equal(style(c, 'display'), 'flex', 'Карточка ' + n + ': display (flex)');
  equal(style(c, 'flex-direction'), 'column', 'Карточка ' + n + ': направление (flex-col)');
  equal(style(c, 'justify-content'), 'space-between', 'Карточка ' + n + ': justify-between');
  equal(style(c, 'height'), '192px', 'Карточка ' + n + ': высота (h-48)');
  equal(style(c, 'background-color'), 'rgb(255, 255, 255)', 'Карточка ' + n + ': фон (bg-white)');
  equal(style(c, 'padding-top'), '16px', 'Карточка ' + n + ': отступ (p-4)');
  equal(style(c, 'border-top-left-radius'), '12px', 'Карточка ' + n + ': скругление (rounded-xl)');
});
var buttons = $$('section article button');
equal(buttons.length, 2, 'Кнопок должно быть две');
buttons.forEach(function(b, i){
  var n = i + 1;
  equal(style(b, 'background-color'), 'rgb(37, 99, 235)', 'Кнопка ' + n + ': фон (bg-blue-600)');
  equal(style(b, 'color'), 'rgb(255, 255, 255)', 'Кнопка ' + n + ': цвет текста');
  equal(style(b, 'padding-left'), '12px', 'Кнопка ' + n + ': отступ (px-3)');
  equal(style(b, 'border-top-left-radius'), '8px', 'Кнопка ' + n + ': скругление (rounded-lg)');
  assert(b.className.indexOf('hover:bg-blue-700') !== -1, 'Кнопка ' + n + ': нет класса hover:bg-blue-700');
});
